#!/bin/bash\n\n# Smoke Tests for AgentScan Deployment\n# Performs basic functionality tests after deployment\n\nset -euo pipefail\n\n# Script configuration\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nPROJECT_ROOT=\"$(dirname \"$(dirname \"$SCRIPT_DIR\")\")\"  # Go up two levels\n\n# Default configuration\nENVIRONMENT=\"production\"\nBASE_URL=\"https://api.agentscan.dev\"\nTIMEOUT=30\nVERBOSE=false\nPARALLEL=false\nOUTPUT_FORMAT=\"text\"  # text, json, junit\nOUTPUT_FILE=\"\"\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Test results\nTOTAL_TESTS=0\nPASSED_TESTS=0\nFAILED_TESTS=0\nSKIPPED_TESTS=0\nTEST_RESULTS=()\n\n# Logging functions\nlog_info() {\n    echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\nlog_success() {\n    echo -e \"${GREEN}[SUCCESS]${NC} $1\"\n}\n\nlog_warning() {\n    echo -e \"${YELLOW}[WARNING]${NC} $1\"\n}\n\nlog_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\nlog_verbose() {\n    if [[ \"$VERBOSE\" == \"true\" ]]; then\n        echo -e \"${BLUE}[VERBOSE]${NC} $1\"\n    fi\n}\n\n# Function to show help\nshow_help() {\n    cat << EOF\nAgentScan Deployment Smoke Tests\n\nUsage: $0 [OPTIONS]\n\nOptions:\n    --environment ENV       Environment to test (default: production)\n    --base-url URL         Base URL for API (default: https://api.agentscan.dev)\n    --timeout SECONDS      Request timeout (default: 30)\n    --verbose              Enable verbose logging\n    --parallel             Run tests in parallel\n    --output-format FORMAT Output format: text, json, junit (default: text)\n    --output-file FILE     Output file for results\n    --help                 Show this help message\n\nExamples:\n    $0 --environment staging --base-url https://staging-api.agentscan.dev\n    $0 --verbose --parallel\n    $0 --output-format junit --output-file test-results.xml\n\nEOF\n}\n\n# Function to make HTTP request\nmake_request() {\n    local method=\"$1\"\n    local endpoint=\"$2\"\n    local expected_status=\"${3:-200}\"\n    local data=\"${4:-}\"\n    \n    local url=\"$BASE_URL$endpoint\"\n    local curl_args=(\n        -s\n        -w \"\\n%{http_code}\\n%{time_total}\\n\"\n        -m \"$TIMEOUT\"\n        -X \"$method\"\n        -H \"Content-Type: application/json\"\n        -H \"User-Agent: AgentScan-SmokeTest/1.0\"\n    )\n    \n    if [[ -n \"$data\" ]]; then\n        curl_args+=(-d \"$data\")\n    fi\n    \n    log_verbose \"Making $method request to $url\"\n    \n    local response\n    response=$(curl \"${curl_args[@]}\" \"$url\" 2>/dev/null || echo \"ERROR\")\n    \n    if [[ \"$response\" == \"ERROR\" ]]; then\n        return 1\n    fi\n    \n    # Parse response (last two lines are status code and time)\n    local body=$(echo \"$response\" | head -n -2)\n    local status_code=$(echo \"$response\" | tail -n 2 | head -n 1)\n    local response_time=$(echo \"$response\" | tail -n 1)\n    \n    log_verbose \"Response status: $status_code, time: ${response_time}s\"\n    \n    if [[ \"$status_code\" == \"$expected_status\" ]]; then\n        echo \"$body\"\n        return 0\n    else\n        log_verbose \"Expected status $expected_status, got $status_code\"\n        return 1\n    fi\n}\n\n# Function to run a test\nrun_test() {\n    local test_name=\"$1\"\n    local test_function=\"$2\"\n    \n    ((TOTAL_TESTS++))\n    \n    log_info \"Running test: $test_name\"\n    \n    local start_time=$(date +%s%3N)\n    local result=\"PASS\"\n    local message=\"\"\n    \n    if $test_function; then\n        ((PASSED_TESTS++))\n        log_success \"✓ $test_name\"\n    else\n        ((FAILED_TESTS++))\n        result=\"FAIL\"\n        log_error \"✗ $test_name\"\n    fi\n    \n    local end_time=$(date +%s%3N)\n    local duration=$((end_time - start_time))\n    \n    TEST_RESULTS+=(\"$test_name|$result|${duration}ms|$message\")\n}\n\n# Function to skip a test\nskip_test() {\n    local test_name=\"$1\"\n    local reason=\"$2\"\n    \n    ((TOTAL_TESTS++))\n    ((SKIPPED_TESTS++))\n    \n    log_warning \"⚠ Skipped: $test_name ($reason)\"\n    TEST_RESULTS+=(\"$test_name|SKIP|0ms|$reason\")\n}\n\n# Test functions\ntest_health_endpoint() {\n    local response\n    response=$(make_request \"GET\" \"/health\" 200)\n    \n    if [[ $? -ne 0 ]]; then\n        return 1\n    fi\n    \n    # Check if response contains expected fields\n    if echo \"$response\" | jq -e '.status' >/dev/null 2>&1; then\n        local status=$(echo \"$response\" | jq -r '.status')\n        if [[ \"$status\" == \"healthy\" ]]; then\n            return 0\n        else\n            log_verbose \"Health status is: $status\"\n            return 1\n        fi\n    else\n        log_verbose \"Invalid health response format\"\n        return 1\n    fi\n}\n\ntest_readiness_endpoint() {\n    local response\n    response=$(make_request \"GET\" \"/ready\" 200)\n    \n    if [[ $? -ne 0 ]]; then\n        return 1\n    fi\n    \n    # Check if response contains expected fields\n    if echo \"$response\" | jq -e '.status' >/dev/null 2>&1; then\n        local status=$(echo \"$response\" | jq -r '.status')\n        if [[ \"$status\" == \"ready\" ]]; then\n            return 0\n        else\n            log_verbose \"Readiness status is: $status\"\n            return 1\n        fi\n    else\n        log_verbose \"Invalid readiness response format\"\n        return 1\n    fi\n}\n\ntest_liveness_endpoint() {\n    local response\n    response=$(make_request \"GET\" \"/live\" 200)\n    \n    if [[ $? -ne 0 ]]; then\n        return 1\n    fi\n    \n    # Check if response contains expected fields\n    if echo \"$response\" | jq -e '.status' >/dev/null 2>&1; then\n        local status=$(echo \"$response\" | jq -r '.status')\n        if [[ \"$status\" == \"alive\" ]]; then\n            return 0\n        else\n            log_verbose \"Liveness status is: $status\"\n            return 1\n        fi\n    else\n        log_verbose \"Invalid liveness response format\"\n        return 1\n    fi\n}\n\ntest_metrics_endpoint() {\n    local response\n    response=$(make_request \"GET\" \"/metrics\" 200)\n    \n    if [[ $? -ne 0 ]]; then\n        return 1\n    fi\n    \n    # Check if response contains expected fields\n    if echo \"$response\" | jq -e '.timestamp' >/dev/null 2>&1; then\n        return 0\n    else\n        log_verbose \"Invalid metrics response format\"\n        return 1\n    fi\n}\n\ntest_api_version() {\n    local response\n    response=$(make_request \"GET\" \"/health\" 200)\n    \n    if [[ $? -ne 0 ]]; then\n        return 1\n    fi\n    \n    # Check if version is present and valid\n    if echo \"$response\" | jq -e '.version' >/dev/null 2>&1; then\n        local version=$(echo \"$response\" | jq -r '.version')\n        if [[ \"$version\" =~ ^[0-9]+\\.[0-9]+\\.[0-9]+$ ]]; then\n            log_verbose \"API version: $version\"\n            return 0\n        else\n            log_verbose \"Invalid version format: $version\"\n            return 1\n        fi\n    else\n        log_verbose \"Version not found in response\"\n        return 1\n    fi\n}\n\ntest_cors_headers() {\n    local response\n    response=$(curl -s -I -X OPTIONS -H \"Origin: https://agentscan.dev\" \"$BASE_URL/health\" 2>/dev/null || echo \"ERROR\")\n    \n    if [[ \"$response\" == \"ERROR\" ]]; then\n        return 1\n    fi\n    \n    # Check for CORS headers\n    if echo \"$response\" | grep -qi \"access-control-allow-origin\"; then\n        log_verbose \"CORS headers present\"\n        return 0\n    else\n        log_verbose \"CORS headers missing\"\n        return 1\n    fi\n}\n\ntest_security_headers() {\n    local response\n    response=$(curl -s -I \"$BASE_URL/health\" 2>/dev/null || echo \"ERROR\")\n    \n    if [[ \"$response\" == \"ERROR\" ]]; then\n        return 1\n    fi\n    \n    # Check for security headers\n    local security_headers=(\"X-Content-Type-Options\" \"X-Frame-Options\")\n    local missing_headers=()\n    \n    for header in \"${security_headers[@]}\"; do\n        if ! echo \"$response\" | grep -qi \"$header\"; then\n            missing_headers+=(\"$header\")\n        fi\n    done\n    \n    if [[ ${#missing_headers[@]} -eq 0 ]]; then\n        log_verbose \"All security headers present\"\n        return 0\n    else\n        log_verbose \"Missing security headers: ${missing_headers[*]}\"\n        return 1\n    fi\n}\n\ntest_response_time() {\n    local start_time=$(date +%s%3N)\n    local response\n    response=$(make_request \"GET\" \"/health\" 200)\n    local end_time=$(date +%s%3N)\n    \n    if [[ $? -ne 0 ]]; then\n        return 1\n    fi\n    \n    local response_time=$((end_time - start_time))\n    log_verbose \"Response time: ${response_time}ms\"\n    \n    # Check if response time is acceptable (< 2 seconds)\n    if [[ $response_time -lt 2000 ]]; then\n        return 0\n    else\n        log_verbose \"Response time too slow: ${response_time}ms\"\n        return 1\n    fi\n}\n\ntest_database_connectivity() {\n    local response\n    response=$(make_request \"GET\" \"/health\" 200)\n    \n    if [[ $? -ne 0 ]]; then\n        return 1\n    fi\n    \n    # Check database health in response\n    if echo \"$response\" | jq -e '.checks.database.status' >/dev/null 2>&1; then\n        local db_status=$(echo \"$response\" | jq -r '.checks.database.status')\n        if [[ \"$db_status\" == \"healthy\" ]]; then\n            return 0\n        else\n            log_verbose \"Database status: $db_status\"\n            return 1\n        fi\n    else\n        log_verbose \"Database check not found in health response\"\n        return 1\n    fi\n}\n\ntest_redis_connectivity() {\n    local response\n    response=$(make_request \"GET\" \"/health\" 200)\n    \n    if [[ $? -ne 0 ]]; then\n        return 1\n    fi\n    \n    # Check Redis health in response\n    if echo \"$response\" | jq -e '.checks.redis.status' >/dev/null 2>&1; then\n        local redis_status=$(echo \"$response\" | jq -r '.checks.redis.status')\n        if [[ \"$redis_status\" == \"healthy\" ]] || [[ \"$redis_status\" == \"disabled\" ]]; then\n            return 0\n        else\n            log_verbose \"Redis status: $redis_status\"\n            return 1\n        fi\n    else\n        log_verbose \"Redis check not found in health response\"\n        return 1\n    fi\n}\n"# Main te
st execution function\nrun_all_tests() {\n    log_info \"Starting smoke tests for environment: $ENVIRONMENT\"\n    log_info \"Base URL: $BASE_URL\"\n    log_info \"Timeout: ${TIMEOUT}s\"\n    echo \"\"\n\n    # Check prerequisites\n    if ! command -v curl &> /dev/null; then\n        log_error \"curl is required but not installed\"\n        exit 1\n    fi\n\n    if ! command -v jq &> /dev/null; then\n        log_error \"jq is required but not installed\"\n        exit 1\n    fi\n\n    # Core health tests\n    run_test \"Health Endpoint\" test_health_endpoint\n    run_test \"Readiness Endpoint\" test_readiness_endpoint\n    run_test \"Liveness Endpoint\" test_liveness_endpoint\n    run_test \"API Version\" test_api_version\n\n    # Performance tests\n    run_test \"Response Time\" test_response_time\n\n    # Security tests\n    run_test \"CORS Headers\" test_cors_headers\n    run_test \"Security Headers\" test_security_headers\n\n    # Infrastructure tests\n    run_test \"Database Connectivity\" test_database_connectivity\n    run_test \"Redis Connectivity\" test_redis_connectivity\n\n    # Monitoring tests\n    run_test \"Metrics Endpoint\" test_metrics_endpoint\n}\n\n# Function to generate test report\ngenerate_report() {\n    local report_file=\"${OUTPUT_FILE:-smoke-test-results.txt}\"\n    \n    case \"$OUTPUT_FORMAT\" in\n        \"json\")\n            generate_json_report \"$report_file\"\n            ;;\n        \"junit\")\n            generate_junit_report \"$report_file\"\n            ;;\n        *)\n            generate_text_report \"$report_file\"\n            ;;\n    esac\n}\n\n# Function to generate text report\ngenerate_text_report() {\n    local report_file=\"$1\"\n    \n    {\n        echo \"AgentScan Smoke Test Results\"\n        echo \"============================\"\n        echo \"Environment: $ENVIRONMENT\"\n        echo \"Base URL: $BASE_URL\"\n        echo \"Timestamp: $(date)\"\n        echo \"\"\n        echo \"Summary:\"\n        echo \"  Total Tests: $TOTAL_TESTS\"\n        echo \"  Passed: $PASSED_TESTS\"\n        echo \"  Failed: $FAILED_TESTS\"\n        echo \"  Skipped: $SKIPPED_TESTS\"\n        echo \"  Success Rate: $(( PASSED_TESTS * 100 / TOTAL_TESTS ))%\"\n        echo \"\"\n        echo \"Test Results:\"\n        echo \"==============\"\n        \n        for result in \"${TEST_RESULTS[@]}\"; do\n            IFS='|' read -r name status duration message <<< \"$result\"\n            printf \"  %-30s %-6s %8s %s\\n\" \"$name\" \"$status\" \"$duration\" \"$message\"\n        done\n    } > \"$report_file\"\n    \n    if [[ -n \"$OUTPUT_FILE\" ]]; then\n        log_success \"Test report saved to: $report_file\"\n    fi\n}\n\n# Function to generate JSON report\ngenerate_json_report() {\n    local report_file=\"$1\"\n    \n    local json_results=\"[]\"\n    for result in \"${TEST_RESULTS[@]}\"; do\n        IFS='|' read -r name status duration message <<< \"$result\"\n        local test_json=$(jq -n \\\n            --arg name \"$name\" \\\n            --arg status \"$status\" \\\n            --arg duration \"$duration\" \\\n            --arg message \"$message\" \\\n            '{\n                name: $name,\n                status: $status,\n                duration: $duration,\n                message: $message\n            }')\n        json_results=$(echo \"$json_results\" | jq \". + [$test_json]\")\n    done\n    \n    jq -n \\\n        --arg environment \"$ENVIRONMENT\" \\\n        --arg base_url \"$BASE_URL\" \\\n        --arg timestamp \"$(date -u +%Y-%m-%dT%H:%M:%SZ)\" \\\n        --argjson total \"$TOTAL_TESTS\" \\\n        --argjson passed \"$PASSED_TESTS\" \\\n        --argjson failed \"$FAILED_TESTS\" \\\n        --argjson skipped \"$SKIPPED_TESTS\" \\\n        --argjson tests \"$json_results\" \\\n        '{\n            environment: $environment,\n            base_url: $base_url,\n            timestamp: $timestamp,\n            summary: {\n                total: $total,\n                passed: $passed,\n                failed: $failed,\n                skipped: $skipped,\n                success_rate: (($passed * 100) / $total)\n            },\n            tests: $tests\n        }' > \"$report_file\"\n    \n    if [[ -n \"$OUTPUT_FILE\" ]]; then\n        log_success \"JSON test report saved to: $report_file\"\n    fi\n}\n\n# Function to generate JUnit XML report\ngenerate_junit_report() {\n    local report_file=\"$1\"\n    \n    {\n        echo '<?xml version=\"1.0\" encoding=\"UTF-8\"?>'\n        echo \"<testsuite name=\\\"AgentScan Smoke Tests\\\" tests=\\\"$TOTAL_TESTS\\\" failures=\\\"$FAILED_TESTS\\\" skipped=\\\"$SKIPPED_TESTS\\\" time=\\\"0\\\">\"\n        \n        for result in \"${TEST_RESULTS[@]}\"; do\n            IFS='|' read -r name status duration message <<< \"$result\"\n            local time_seconds=$(echo \"$duration\" | sed 's/ms$//' | awk '{print $1/1000}')\n            \n            echo \"  <testcase name=\\\"$name\\\" classname=\\\"SmokeTests\\\" time=\\\"$time_seconds\\\">\"\n            \n            case \"$status\" in\n                \"FAIL\")\n                    echo \"    <failure message=\\\"Test failed\\\">$message</failure>\"\n                    ;;\n                \"SKIP\")\n                    echo \"    <skipped message=\\\"Test skipped\\\">$message</skipped>\"\n                    ;;\n            esac\n            \n            echo \"  </testcase>\"\n        done\n        \n        echo \"</testsuite>\"\n    } > \"$report_file\"\n    \n    if [[ -n \"$OUTPUT_FILE\" ]]; then\n        log_success \"JUnit XML report saved to: $report_file\"\n    fi\n}\n\n# Function to print summary\nprint_summary() {\n    echo \"\"\n    log_info \"Test Summary\"\n    echo \"============\"\n    echo \"Total Tests: $TOTAL_TESTS\"\n    echo \"Passed: $PASSED_TESTS\"\n    echo \"Failed: $FAILED_TESTS\"\n    echo \"Skipped: $SKIPPED_TESTS\"\n    \n    if [[ $TOTAL_TESTS -gt 0 ]]; then\n        local success_rate=$(( PASSED_TESTS * 100 / TOTAL_TESTS ))\n        echo \"Success Rate: ${success_rate}%\"\n        \n        if [[ $FAILED_TESTS -eq 0 ]]; then\n            log_success \"All tests passed! 🎉\"\n        else\n            log_error \"$FAILED_TESTS test(s) failed\"\n        fi\n    fi\n    \n    echo \"\"\n}\n\n# Main execution\nmain() {\n    # Run tests\n    run_all_tests\n    \n    # Generate report\n    generate_report\n    \n    # Print summary\n    print_summary\n    \n    # Exit with appropriate code\n    if [[ $FAILED_TESTS -gt 0 ]]; then\n        exit 1\n    else\n        exit 0\n    fi\n}\n\n# Parse command line arguments\nwhile [[ $# -gt 0 ]]; do\n    case $1 in\n        --environment)\n            ENVIRONMENT=\"$2\"\n            shift 2\n            ;;\n        --base-url)\n            BASE_URL=\"$2\"\n            shift 2\n            ;;\n        --timeout)\n            TIMEOUT=\"$2\"\n            shift 2\n            ;;\n        --verbose)\n            VERBOSE=true\n            shift\n            ;;\n        --parallel)\n            PARALLEL=true\n            shift\n            ;;\n        --output-format)\n            OUTPUT_FORMAT=\"$2\"\n            shift 2\n            ;;\n        --output-file)\n            OUTPUT_FILE=\"$2\"\n            shift 2\n            ;;\n        --help|-h)\n            show_help\n            exit 0\n            ;;\n        *)\n            log_error \"Unknown option: $1\"\n            show_help\n            exit 1\n            ;;\n    esac\ndone\n\n# Set environment-specific defaults\ncase \"$ENVIRONMENT\" in\n    \"staging\")\n        BASE_URL=\"${BASE_URL:-https://staging-api.agentscan.dev}\"\n        ;;\n    \"development\")\n        BASE_URL=\"${BASE_URL:-http://localhost:8080}\"\n        ;;\n    \"production\")\n        BASE_URL=\"${BASE_URL:-https://api.agentscan.dev}\"\n        ;;\nesac\n\n# Make script executable\nchmod +x \"$0\"\n\n# Run main function\nmain\n"